if (typeof jirav === 'undefined') throw new Error('Paste scripts/jirav.min.js (the core) first.');

jirav.block('customTableStructure','7a85fc9b', jirav => {
  const onPage = () => {
    if (!/\/setup\/custom-tables/.test(location.pathname)) throw new Error('Open Settings → Custom Tables first.');
  };
  const clean = s => (s || '').replace(/drag_indicator|more_vert/g, '').replace(/\s+/g, ' ').trim();
  const sidebarItems = () => jirav.deepAll(document, 'jirav-ng-left-sidebar-item');
  const tables = async () => {
    onPage();
    const ids = Object.fromEntries((await jirav.listCustomTables()).map(t => [ t.name, t.id ]));
    return sidebarItems().map(it => {
      const name = clean(it.textContent), btn = it.querySelector('.dropdown-button-container');
      return {
        name: name,
        id: ids[name] || null,
        active: it.classList.contains('m-active'),
        menu: btn ? jirav.at(btn) : null
      };
    });
  };
  const active = () => {
    onPage();
    const it = sidebarItems().find(i => i.classList.contains('m-active'));
    return it ? clean(it.textContent) : null;
  };
  const open = async name => {
    const all = await jirav.listCustomTables();
    const t = all.find(x => x.name === name) || all.filter(x => x.name.toLowerCase() === String(name).toLowerCase())[0];
    if (!t) throw new Error(`No custom table "${name}". Tables: ${all.map(x => x.name).join(', ')}`);
    const enc = [ 0, 1, 2 ].reduce(v => encodeURIComponent(v), t.name.toLowerCase());
    await jirav.go(`/${location.pathname.split('/')[1]}/setup/custom-tables/${enc}`);
    for (let i = 0; i < 40; i++) {
      const a = /\/setup\/custom-tables/.test(location.pathname) && active();
      if (a === t.name) return {
        ok: true,
        active: a,
        id: t.id
      };
      await new Promise(r => setTimeout(r, 250));
    }
    const a = /\/setup\/custom-tables/.test(location.pathname) ? active() : null;
    return {
      ok: false,
      active: a,
      why: `Asked for "${t.name}" but "${a}" is open: don't edit; click "${t.name}" in the sidebar.`
    };
  };
  const openTableMenu = async name => {
    onPage();
    const it = sidebarItems().find(i => clean(i.textContent) === name);
    if (!it) throw new Error(`No table "${name}" in the sidebar.`);
    const c = it.querySelector('.dropdown-button-container');
    (c.querySelector('button') || c).click();
    await new Promise(r => setTimeout(r, 500));
    return jirav.deepAll(document, 'button').filter(b => b.getBoundingClientRect().height > 0 && /^(Rename|Delete|Move Up|Move Down)$/.test(b.textContent.trim())).map(b => ({
      label: b.textContent.trim(),
      ...jirav.at(b)
    }));
  };
  const describe = el => {
    const item = el.closest('.muuri-item');
    const txt = el.innerText || '';
    const typeTxt = (txt.match(/ROW TYPE\s*\n\s*([^\n]+)/i) || [])[1] || (/Blank Row/i.test(txt) ? 'Blank Row' : '');
    const type = {
      'New Line': 'line',
      Section: 'section',
      Reference: 'reference',
      Subtotal: 'subtotal',
      'Blank Row': 'blank'
    }[typeTxt.trim()] || typeTxt.trim().toLowerCase();
    const input = el.querySelector('input.movable-input');
    const headName = it => {
      const h = [ ...it.querySelectorAll('input.movable-input') ].find(i => i.closest('.muuri-item') === it);
      return h ? h.value : null;
    };
    const name = type === 'reference' ? ((txt.match(/\nREFERENCE\s*\n\s*([^\n]+)/) || [])[1] || 'Reference').trim() : type === 'subtotal' ? `Subtotal ${headName(item) || ''}`.trim() : input ? input.value : type === 'blank' ? 'Blank Row' : '';
    let depth = 0, section = null, p = item.parentElement && item.parentElement.closest('.muuri-item');
    if (type === 'subtotal') {
      section = headName(item);
      depth = 1;
    }
    while (p) {
      depth++;
      if (section === null) section = headName(p);
      p = p.parentElement && p.parentElement.closest('.muuri-item');
    }
    const btn = el.querySelector('.jv-action-menu-container button');
    const glyph = btn && (() => {
      const c = jirav.at(btn);
      return {
        x: c.x - 3,
        y: c.y + 2
      };
    })();
    return {
      name: name,
      type: type,
      depth: depth,
      section: section,
      moving: el.classList.contains('draggable'),
      menu: glyph || null,
      _item: item
    };
  };
  const allRows = () => {
    onPage();
    return [ ...document.querySelectorAll('.movable-group-element') ].filter(e => e.closest('.muuri-item') && e.closest('.movable-group-element-container')).map(describe);
  };
  const strip = r => {
    const {_item: _item, ...rest} = r;
    return rest;
  };
  const rows = () => allRows().map(strip);
  const find = name => {
    const hits = allRows().filter(r => r.name === name);
    if (!hits.length) throw new Error(`No row named "${name}". Rows: ${allRows().map(r => r.name).join(', ')}`);
    if (hits.length > 1) throw new Error(`${hits.length} rows are named "${name}"; rename one first or pick by position from ct.rows().`);
    return hits[0];
  };
  const row = name => strip(find(name));
  const moving = () => {
    const r = allRows().find(x => x.moving);
    return r ? r.name : null;
  };
  const pending = () => {
    const shown = b => {
      const r = b.getBoundingClientRect();
      return r.height > 0 && r.top < innerHeight && getComputedStyle(b).visibility !== 'hidden';
    };
    const btn = t => [ ...document.querySelectorAll('button, a') ].find(b => b.textContent.trim().toUpperCase() === t && shown(b));
    const s = btn('SAVE CHANGES'), c = btn('CANCEL');
    const blocked = !!s && !!(s.disabled || s.getAttribute('aria-disabled') === 'true' || s.closest('[disabled], [aria-disabled="true"]')), tip = s && s.closest('[data-tooltip]');
    return {
      pending: !!s,
      blocked: blocked,
      ...blocked ? {
        reason: tip && tip.getAttribute('data-tooltip') || null
      } : {},
      save: s ? jirav.at(s) : null,
      cancel: c ? jirav.at(c) : null
    };
  };
  const structure = async () => {
    onPage();
    const active = sidebarItems().find(i => i.classList.contains('m-active'));
    const name = active && clean(active.textContent);
    const t = (await jirav.listCustomTables()).find(x => x.name === name);
    if (!t) throw new Error('Could not tell which table is open.');
    const {base: base} = await jirav.getTenant();
    const r = await jirav.fetch(`${base}/v1/customTable/${t.id}`, {
      credentials: 'include'
    }).then(r => r.json());
    const walk = e => {
      const k = Object.keys(e)[0], v = e[k];
      const label = v.label || (k === 'separator' ? '(blank row)' : k === 'lineReference' ? `(reference ${v.address && v.address.category})` : '');
      const s = {
        type: k,
        id: v.id,
        label: label
      };
      if (v.format) s.format = v.format;
      if (v.aggregation) s.periodValue = v.aggregation;
      if (k === 'section') {
        s.subtotal = v.subtotal;
        s.children = v.children.map(walk);
      }
      return s;
    };
    return {
      id: t.id,
      name: name,
      elements: (r.customTableConfig || r).elements.map(walk)
    };
  };
  const check = async () => {
    const st = await structure(), out = [];
    const lines = el => el.type === 'manualLine' ? [ el ] : el.type === 'section' ? el.children.flatMap(lines) : [];
    const visit = (el, path) => {
      if (el.type !== 'section') return;
      const p = path.concat(el.label), ls = lines(el);
      if (!el.subtotal) {
        el.children.forEach(c => visit(c, p));
        return;
      }
      const fmts = [ ...new Set(ls.map(l => l.format).filter(Boolean)) ], pvs = [ ...new Set(ls.map(l => l.periodValue).filter(Boolean)) ];
      if (fmts.length > 1) out.push({
        section: p.join(' › '),
        problem: `mixed Format: ${fmts.join(', ')}`,
        lines: ls.map(l => `${l.label} (${l.format})`)
      });
      if (pvs.length > 1) out.push({
        section: p.join(' › '),
        problem: `mixed Period Value: ${pvs.join(', ')}`,
        lines: ls.map(l => `${l.label} (${l.periodValue})`)
      });
      if (el.children.some(c => c.type === 'lineReference') && ls.length) out.push({
        section: p.join(' › '),
        problem: 'has a Reference row next to lines: check its format and Period Value match, and that the section row isn\'t red in a plan'
      });
      el.children.forEach(c => visit(c, p));
    };
    st.elements.forEach(e => visit(e, []));
    return out;
  };
  const move = async (name, target, opts) => {
    const r = find(name), t = find(target);
    if (r.type === 'subtotal' || t.type === 'subtotal') return {
      ok: false,
      why: 'A Subtotal row moves with its section: move the section, or target a line.'
    };
    if (!r.moving) return {
      ok: false,
      why: `"${name}" is not in Move mode: click its ⋯ (ct.row(name).menu) and choose Move first.`
    };
    const res = await jirav.drag(r._item, t._item, opts);
    return Object.assign(res, {
      order: rows().map(x => (x.depth ? '  '.repeat(x.depth) : '') + x.name)
    });
  };
  return {
    tables: tables,
    active: active,
    open: open,
    openTableMenu: openTableMenu,
    rows: rows,
    row: row,
    moving: moving,
    pending: pending,
    structure: structure,
    check: check,
    move: move
  };
}, 'Settings → Custom Tables editor: rows, menus, Save bar, structure, drag a row in Move mode');